package com.zhku.knowledge.ruleagent;
import com.zhku.agent.agent.runtime.*;
import com.zhku.knowledge.rulecheck.*;
import com.zhku.knowledge.retrieval.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.*;
import static com.zhku.knowledge.ruleagent.RuleAgentContract.*;
import static org.assertj.core.api.Assertions.*;

@Timeout(15)
class RuleAgentTaskStoreTest {
    final Owner owner=new Owner(UUID.randomUUID(),UUID.randomUUID());final Queue<Runnable> queued=new ConcurrentLinkedQueue<>();final AtomicInteger decisions=new AtomicInteger();final AtomicBoolean revoked=new AtomicBoolean();
    final AtomicReference<Instant> time=new AtomicReference<>(Instant.parse("2026-10-13T08:00:00Z"));
    final Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return this;}public Instant instant(){return time.get();}};
    RuleAgentTaskStore store(){return new RuleAgentTaskStore(queued::add,this::work,clock,new RuleAgentTaskStore.Limits(8,4,32));}
    void drain(){Runnable r;while((r=queued.poll())!=null)r.run();}
    RuleAgentTaskStore.Work work(Owner actor,UUID task){
        return work(actor,task,List.of("kind"));
    }
    RuleAgentTaskStore.Work work(Owner actor,UUID task,List<String> keys){
        try{UUID source=UUID.randomUUID(),chunk=UUID.randomUUID();String text="合成类别规则，A类可核对。";String hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));
            var binding=new RuleCheckRuleTemplate.EvidenceBinding(source,chunk,"2025.9.2",hash,0,text.length(),text);
            var when=new LinkedHashMap<String,String>();keys.forEach(k->when.put(k,"A"));
            var fact=new RuleCheckRuleTemplate.Fact("fact","A类合成解释",true,when,List.of(binding));
            var rule=new RuleCheckRuleTemplate("r","2025.9.2",RuleCheckRuleTemplate.ReviewState.APPROVED,"synthetic",LocalDate.of(2026,10,13),List.of(fact),keys.stream().map(k->new RuleCheckRuleTemplate.Condition(k,"请选择类别",List.of("A","B"))).toList(),List.of(),List.of());
            var entry=new RuleCheckApplicationService.CatalogEntry(rule,"合成类别范围",new RuleCheckApplicabilityGuard.Coverage(Set.of(RuleCheckApplicabilityGuard.Audience.UNDERGRADUATE)),RuleCheckTopicGuard.Coverage.declared(RuleCheckTopicGuard.Topic.CATEGORY));
            var snapshot=new RuleCheckEvidenceSnapshot("current",source,chunk,"2025.9.2",hash,text,true);var candidate=new RetrievedChunk(chunk,text,"synthetic","synthetic",1,"2025.9.2",hash,source);
            var tools=new RuleAgentEvidenceTools(actor,task,new RuleCheckRuntimeSettings("p","c","s","2025.9.2",20,5),()->List.of(entry),(q,n)->List.of(candidate),(s,c)->revoked.get()?Optional.empty():Optional.of(snapshot),r->{},clock);
            return new RuleAgentTaskStore.Work(){
                public RuleAgentRunner.Outcome run(AgentRunContext context,RuleAgentRunner.Input input){
                    RuleAgentRunner.DecisionPort port=(v,t)->{decisions.incrementAndGet();NextAction action;if(v.observations().isEmpty())action=new Search("q1","类别");else if(v.facts().isEmpty())action=new Read("q1",List.of(v.observations().getLast().candidates().getFirst().handle()));else if(keys.stream().anyMatch(k->!v.userConditions().containsKey(k)))action=new Ask("q1",keys.stream().filter(k->!v.userConditions().containsKey(k)).findFirst().orElseThrow(),"必要条件",List.of("r:fact"));else action=new Finish(List.of(new Proposal("q1",List.of("r:fact"),List.of(),null)));try{return new RuleAgentRunner.Reply(new ObjectMapper().writeValueAsString(action),false);}catch(Exception e){throw new IllegalStateException(e);}};
                    return new RuleAgentRunner(port,new RuleActionBroker(tools),clock).run(context,input);
                }
                public boolean revalidate(ResultEnvelope result){return result.evidence().stream().allMatch(e->tools.original(actor,task,e.originalToken()).isPresent());}
            };
        }catch(Exception e){throw new IllegalStateException(e);}
    }
    RuleAgentTaskStore.Accepted waiting(RuleAgentTaskStore s){var a=s.create(owner,new CreateTask("课程类别是什么？",UUID.randomUUID()));drain();assertThat(s.snapshot(owner,a.taskId()).taskStatus()).isEqualTo(TaskStatus.WAITING_USER);return a;}
    Message reply(TaskSnapshot s,UUID key){return new Message("A",s.continuationToken(),s.version(),key);}
    @Test void duplicateCreateAndLostResponseLookupReturnSameRun(){try(var s=store()){UUID key=UUID.randomUUID();var request=new CreateTask("课程类别是什么？",key);var a=s.create(owner,request);var b=s.create(owner,request);assertThat(b.runId()).isEqualTo(a.runId());assertThat(b.duplicate()).isTrue();assertThat(s.lookup(owner,RequestAction.CREATE,key).runId()).isEqualTo(a.runId());assertThat(queued).hasSize(1);drain();assertThat(decisions).hasValue(3);}}
    @Test void sameKeyDifferentPayloadIsConflict(){try(var s=store()){UUID key=UUID.randomUUID();s.create(owner,new CreateTask("课程类别是什么？",key));assertThatThrownBy(()->s.create(owner,new CreateTask("改变问题",key))).isInstanceOf(RuleAgentTaskStore.Failure.class);assertThat(queued).hasSize(1);}}
    @Test void clarificationResumesSameTaskNewRunWithoutRepeatingKnownCondition(){try(var s=store()){var first=waiting(s);var before=s.snapshot(owner,first.taskId());var a=s.message(owner,first.taskId(),reply(before,UUID.randomUUID()));assertThat(a.taskId()).isEqualTo(first.taskId());assertThat(a.runId()).isNotEqualTo(first.runId());assertThat(s.snapshot(owner,first.taskId()).taskStatus()).isEqualTo(TaskStatus.ACTIVE);drain();var finalState=s.snapshot(owner,first.taskId());assertThat(finalState.taskStatus()).isEqualTo(TaskStatus.RESOLVED);assertThat(finalState.result().items().getFirst().clarification()).isEmpty();assertThat(s.history(owner,first.taskId())).hasSize(2);assertThat(decisions).hasValue(6);assertThat(s.activeJobs()).isZero();}}
    @Test void duplicateReplyDoesNotDispatchAgain(){try(var s=store()){var a=waiting(s);var before=s.snapshot(owner,a.taskId());var m=reply(before,UUID.randomUUID());var first=s.message(owner,a.taskId(),m);var duplicate=s.message(owner,a.taskId(),m);assertThat(duplicate.runId()).isEqualTo(first.runId());assertThat(queued).hasSize(1);drain();assertThat(decisions).hasValue(6);}}
    @Test void concurrentRepliesAcceptOnlyOneVersion()throws Exception{try(var s=store()){var a=waiting(s);var before=s.snapshot(owner,a.taskId());var start=new CountDownLatch(1);var accepted=new AtomicInteger();var rejected=new AtomicInteger();var executor=Executors.newFixedThreadPool(2);try{var jobs=new ArrayList<Future<?>>();for(int i=0;i<2;i++)jobs.add(executor.submit(()->{try{start.await();s.message(owner,a.taskId(),reply(before,UUID.randomUUID()));accepted.incrementAndGet();}catch(RuleAgentTaskStore.Failure e){rejected.incrementAndGet();}catch(InterruptedException e){Thread.currentThread().interrupt();}}));start.countDown();for(var j:jobs)j.get(2,TimeUnit.SECONDS);}finally{executor.shutdownNow();}assertThat(accepted).hasValue(1);assertThat(rejected).hasValue(1);assertThat(queued).hasSize(1);}}
    @Test void foreignSessionWrongTokenAndExpiredTokenCannotResume(){try(var s=store()){var a=waiting(s);var before=s.snapshot(owner,a.taskId());var foreign=new Owner(owner.actorId(),UUID.randomUUID());assertThatThrownBy(()->s.message(foreign,a.taskId(),reply(before,UUID.randomUUID()))).isInstanceOf(RuleAgentTaskStore.Failure.class);assertThatThrownBy(()->s.message(owner,a.taskId(),new Message("A",UUID.randomUUID(),before.version(),UUID.randomUUID()))).isInstanceOf(RuleAgentTaskStore.Failure.class);time.set(time.get().plusMillis(DEFAULT_BUDGET.waitingTtlMillis()));assertThatThrownBy(()->s.message(owner,a.taskId(),reply(before,UUID.randomUUID()))).isInstanceOf(RuleAgentTaskStore.Failure.class);assertThat(queued).isEmpty();}}
    @Test void changedGoalNeedsNewTaskAndAmbiguousReplyNeedsConfirmation(){try(var s=store()){var a=waiting(s);var before=s.snapshot(owner,a.taskId());assertThatThrownBy(()->s.message(owner,a.taskId(),new Message("改问奖学金条件",before.continuationToken(),before.version(),UUID.randomUUID()))).isInstanceOf(RuleAgentTaskStore.Failure.class);assertThatThrownBy(()->s.message(owner,a.taskId(),new Message("也许是其他类别",before.continuationToken(),before.version(),UUID.randomUUID()))).isInstanceOf(RuleAgentTaskStore.Failure.class);assertThat(s.snapshot(owner,a.taskId()).continuationToken()).isEqualTo(before.continuationToken());}}
    @Test void withdrawnEvidenceStopsContinuationWithoutMoreDecisions(){try(var s=store()){var a=waiting(s);var before=s.snapshot(owner,a.taskId());revoked.set(true);assertThatThrownBy(()->s.message(owner,a.taskId(),reply(before,UUID.randomUUID()))).isInstanceOf(RuleAgentTaskStore.Failure.class);assertThat(decisions).hasValue(3);assertThat(queued).isEmpty();}}
    @Test void queuedCancellationProducesNoModelAttemptsAndHasIdempotentReceipt(){try(var s=store()){var a=s.create(owner,new CreateTask("课程类别是什么？",UUID.randomUUID()));var cancel=new Cancel(a.runId(),a.version(),UUID.randomUUID());s.cancel(owner,a.taskId(),cancel);s.cancel(owner,a.taskId(),cancel);assertThat(s.snapshot(owner,a.taskId()).terminated()).isFalse();drain();var result=s.snapshot(owner,a.taskId());assertThat(result.taskStatus()).isEqualTo(TaskStatus.STOPPED);assertThat(result.runState()).isEqualTo(AgentRunState.CANCELLED);assertThat(decisions).hasValue(0);assertThat(s.activeJobs()).isZero();}}
    @Test void boundedCapacityAndNewStoreReportUnavailableInsteadOfHistory(){try(var s=new RuleAgentTaskStore(queued::add,this::work,clock,new RuleAgentTaskStore.Limits(1,1,4))){var a=s.create(owner,new CreateTask("课程类别是什么？",UUID.randomUUID()));assertThatThrownBy(()->s.create(owner,new CreateTask("另一任务",UUID.randomUUID()))).isInstanceOf(RuleAgentTaskStore.Failure.class);try(var restarted=store()){assertThatThrownBy(()->restarted.snapshot(owner,a.taskId())).isInstanceOf(RuleAgentTaskStore.Failure.class);assertThat(decisions).hasValue(0);}}}
    @Test void thirdClarificationCannotLeaveAnUnresumableWaitingTask(){try(var s=new RuleAgentTaskStore(queued::add,(o,t)->work(o,t,List.of("kind","second","third")),clock,new RuleAgentTaskStore.Limits(8,4,32))){var a=waiting(s);for(int i=0;i<2;i++){var before=s.snapshot(owner,a.taskId());s.message(owner,a.taskId(),reply(before,UUID.randomUUID()));drain();}var result=s.snapshot(owner,a.taskId());assertThat(result.taskStatus()).isEqualTo(TaskStatus.STOPPED);assertThat(result.continuationToken()).isNull();assertThat(result.result().items().getFirst().issues().getFirst().reasonCode()).isEqualTo(ReasonCode.BUDGET_EXCEEDED);assertThat(s.history(owner,a.taskId())).hasSize(3);}}
    @Test void fullRequestIndexStillReturnsDuplicateWithoutCapacityLeak(){try(var s=new RuleAgentTaskStore(queued::add,this::work,clock,new RuleAgentTaskStore.Limits(4,4,1))){var request=new CreateTask("课程类别是什么？",UUID.randomUUID());var a=s.create(owner,request);assertThat(s.create(owner,request).runId()).isEqualTo(a.runId());assertThatThrownBy(()->s.create(owner,new CreateTask("另一问题",UUID.randomUUID()))).isInstanceOf(RuleAgentTaskStore.Failure.class);assertThat(queued).hasSize(1);}}
    @Test void dispatchFailureIsRecordedAndContractCanBeConsumedByFrontend()throws Exception{
        try(var s=new RuleAgentTaskStore(r->{throw new RejectedExecutionException("synthetic");},this::work,clock,new RuleAgentTaskStore.Limits(8,4,32))){var a=s.create(owner,new CreateTask("课程类别是什么？",UUID.randomUUID()));var snapshot=s.snapshot(owner,a.taskId());assertThat(snapshot.taskStatus()).isEqualTo(TaskStatus.FAILED);assertThat(snapshot.result().items().getFirst().issues().getFirst().reasonCode().name()).isEqualTo("TASK_EXECUTION_UNAVAILABLE");assertThat(decisions).hasValue(0);new ObjectMapper().writerWithDefaultPrettyPrinter().writeValue(java.nio.file.Path.of(System.getProperty("zhku.rulecheck.evidenceDir"),"dispatch-failure-snapshot.json").toFile(),snapshot);}
    }
    @Test void blockedWorkDoesNotHoldStoreLockAndCancellationWaitsForRealExit()throws Exception{
        var started=new CountDownLatch(1);var release=new CountDownLatch(1);var context=new AtomicReference<AgentRunContext>();var executor=Executors.newSingleThreadExecutor();
        try(var s=new RuleAgentTaskStore(executor,(o,t)->{var delegate=work(o,t);return new RuleAgentTaskStore.Work(){public RuleAgentRunner.Outcome run(AgentRunContext c,RuleAgentRunner.Input i){context.set(c);started.countDown();boolean done=false;while(!done){try{release.await();done=true;}catch(InterruptedException ignored){}}return delegate.run(c,i);}public boolean revalidate(ResultEnvelope r){return delegate.revalidate(r);}};},clock,new RuleAgentTaskStore.Limits(8,4,32))){
            var a=s.create(owner,new CreateTask("课程类别是什么？",UUID.randomUUID()));assertThat(started.await(2,TimeUnit.SECONDS)).isTrue();assertThat(s.snapshot(owner,a.taskId()).taskStatus()).isEqualTo(TaskStatus.ACTIVE);s.cancel(owner,a.taskId(),new Cancel(a.runId(),a.version(),UUID.randomUUID()));assertThat(context.get().termination()).isNotCompleted();assertThat(s.snapshot(owner,a.taskId()).terminated()).isFalse();release.countDown();executor.submit(()->{}).get(2,TimeUnit.SECONDS);assertThat(s.snapshot(owner,a.taskId()).taskStatus()).isEqualTo(TaskStatus.STOPPED);assertThat(s.activeJobs()).isZero();assertThat(decisions).hasValue(0);
        }finally{release.countDown();executor.shutdownNow();executor.awaitTermination(2,TimeUnit.SECONDS);}
    }
}
